mapper.select:
select t1.*,t2.PROJECT_NAME as implementationProjectName,t2.PROJECT_ORDER_NAME as implementationPlanMainReviewer,
t2.PROJECT_TYPE as implementationProjectType,t2.PROJECT_ORDER_ID as implementationProjectOrderId,t2.SJLX_NAME as sjlxName
from TBL_CEA_PROJECT_DECLARE t1
left join TBL_YQNS_IMPLEMENT_PLAN t2 on t2.ID = t1.IMPLEMENTATIONPLANID
where 1=1
and (t1.creator = #{param.creator}

   or t1.creator in (SELECT DISTINCT STAFFID FROM TBL_USER_ORGRELATION WHERE DEPTID IN (${param.getDeptIds}))
)

    and t2.PROJECT_NAME like concat('%',concat(#{param.implementationProjectName},'%'))


    and t1.state = #{param.state}


    and t1.id not in

        #{item}



    and t1.id in

        #{item}



    and t1.groupId = #{param.groupId}


    and t1.groupId IS NULL


    and t1.groupId IS NOT NULL


    and t1.flag_abandoned = #{param.flagAbandoned}


    order by t1.RESULTSORT,t1.ID


    order by t1.ID desc

select t1.*,t2.PROJECT_NAME as implementationProjectName
from TBL_CEA_PROJECT_DECLARE t1
inner join TBL_CEA_PROJECT_DECLARE_GROUP t3 on t3.id = t1.GROUPID
left join TBL_YQNS_IMPLEMENT_PLAN t2 on t2.ID = t1.IMPLEMENTATIONPLANID
where (t1.creator = #{param.creator}

   or t1.creator in (SELECT DISTINCT STAFFID FROM TBL_USER_ORGRELATION WHERE DEPTID IN (${param.getDeptIds}))
)

    and t3.state = #{param.state}


    and t2.PROJECT_NAME like concat('%',concat(#{param.implementationProjectName},'%'))

order by t1.RESULTSORT ,t1.ID
